CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

CREATE TABLE "Region" (
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "Code" text NULL,
    "Name" text NULL,
    CONSTRAINT "PK_Region" PRIMARY KEY ("Id")
);

CREATE TABLE "LookupCode" (
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "CreatedById" uuid NULL,
    "CreatedOn" timestamp without time zone NOT NULL,
    "UpdatedById" uuid NULL,
    "UpdatedOn" timestamp without time zone NULL,
    "RowVersion" bytea NULL,
    "Type" integer NOT NULL,
    "Code" text NULL,
    "SubCode" text NULL,
    "Description" text NULL,
    "EffectiveDate" timestamp without time zone NULL,
    "ExpiryDate" timestamp without time zone NULL,
    "SortOrder" integer NULL,
    "LocationId" integer NULL,
    CONSTRAINT "PK_LookupCode" PRIMARY KEY ("Id")
);

CREATE TABLE "SheriffAwayLocation" (
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "CreatedById" uuid NULL,
    "CreatedOn" timestamp without time zone NOT NULL,
    "UpdatedById" uuid NULL,
    "UpdatedOn" timestamp without time zone NULL,
    "RowVersion" bytea NULL,
    "LocationId" integer NULL,
    "StartDate" timestamp without time zone NULL,
    "EndDate" timestamp without time zone NULL,
    "IsFullDay" boolean NOT NULL,
    "SheriffId" uuid NULL,
    CONSTRAINT "PK_SheriffAwayLocation" PRIMARY KEY ("Id")
);

CREATE TABLE "User" (
    "Id" uuid NOT NULL,
    "CreatedById" uuid NULL,
    "CreatedOn" timestamp without time zone NOT NULL,
    "UpdatedById" uuid NULL,
    "UpdatedOn" timestamp without time zone NULL,
    "RowVersion" bytea NULL,
    "PreferredUsername" text NULL,
    "IdirId" uuid NOT NULL,
    "IsDisabled" boolean NOT NULL,
    "HomeLocationId" integer NULL,
    "FirstName" text NULL,
    "LastName" text NULL,
    "Email" text NULL,
    "LastLogin" timestamp without time zone NULL,
    "Discriminator" text NOT NULL,
    "Gender" integer NULL,
    "BadgeNumber" text NULL,
    "Rank" text NULL,
    "Photo" bytea NULL,
    CONSTRAINT "PK_User" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_User_User_CreatedById" FOREIGN KEY ("CreatedById") REFERENCES "User" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_User_User_UpdatedById" FOREIGN KEY ("UpdatedById") REFERENCES "User" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Location" (
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "CreatedById" uuid NULL,
    "CreatedOn" timestamp without time zone NOT NULL,
    "UpdatedById" uuid NULL,
    "UpdatedOn" timestamp without time zone NULL,
    "RowVersion" bytea NULL,
    "Code" text NULL,
    "Name" text NULL,
    "JustinId" integer NOT NULL,
    "JustinCode" text NULL,
    "ParentLocationId" integer NOT NULL,
    "RegionId" integer NULL,
    CONSTRAINT "PK_Location" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Location_User_CreatedById" FOREIGN KEY ("CreatedById") REFERENCES "User" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Location_Region_RegionId" FOREIGN KEY ("RegionId") REFERENCES "Region" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Location_User_UpdatedById" FOREIGN KEY ("UpdatedById") REFERENCES "User" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Permission" (
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "CreatedById" uuid NULL,
    "CreatedOn" timestamp without time zone NOT NULL,
    "UpdatedById" uuid NULL,
    "UpdatedOn" timestamp without time zone NULL,
    "RowVersion" bytea NULL,
    "Name" text NULL,
    "Description" text NULL,
    "UserId" uuid NULL,
    CONSTRAINT "PK_Permission" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Permission_User_CreatedById" FOREIGN KEY ("CreatedById") REFERENCES "User" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Permission_User_UpdatedById" FOREIGN KEY ("UpdatedById") REFERENCES "User" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Permission_User_UserId" FOREIGN KEY ("UserId") REFERENCES "User" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Role" (
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "CreatedById" uuid NULL,
    "CreatedOn" timestamp without time zone NOT NULL,
    "UpdatedById" uuid NULL,
    "UpdatedOn" timestamp without time zone NULL,
    "RowVersion" bytea NULL,
    "Name" text NULL,
    "Description" text NULL,
    CONSTRAINT "PK_Role" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Role_User_CreatedById" FOREIGN KEY ("CreatedById") REFERENCES "User" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Role_User_UpdatedById" FOREIGN KEY ("UpdatedById") REFERENCES "User" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "SheriffLeave" (
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "CreatedById" uuid NULL,
    "CreatedOn" timestamp without time zone NOT NULL,
    "UpdatedById" uuid NULL,
    "UpdatedOn" timestamp without time zone NULL,
    "RowVersion" bytea NULL,
    "LeaveTypeId" integer NULL,
    "StartDate" timestamp without time zone NULL,
    "EndDate" timestamp without time zone NULL,
    "IsFullDay" boolean NOT NULL,
    "SheriffId" uuid NULL,
    CONSTRAINT "PK_SheriffLeave" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_SheriffLeave_User_CreatedById" FOREIGN KEY ("CreatedById") REFERENCES "User" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_SheriffLeave_LookupCode_LeaveTypeId" FOREIGN KEY ("LeaveTypeId") REFERENCES "LookupCode" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_SheriffLeave_User_SheriffId" FOREIGN KEY ("SheriffId") REFERENCES "User" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_SheriffLeave_User_UpdatedById" FOREIGN KEY ("UpdatedById") REFERENCES "User" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "SheriffTraining" (
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "CreatedById" uuid NULL,
    "CreatedOn" timestamp without time zone NOT NULL,
    "UpdatedById" uuid NULL,
    "UpdatedOn" timestamp without time zone NULL,
    "RowVersion" bytea NULL,
    "TrainingTypeId" integer NULL,
    "StartDate" timestamp without time zone NULL,
    "EndDate" timestamp without time zone NULL,
    "IsFullDay" boolean NOT NULL,
    "SheriffId" uuid NULL,
    CONSTRAINT "PK_SheriffTraining" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_SheriffTraining_User_CreatedById" FOREIGN KEY ("CreatedById") REFERENCES "User" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_SheriffTraining_User_SheriffId" FOREIGN KEY ("SheriffId") REFERENCES "User" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_SheriffTraining_LookupCode_TrainingTypeId" FOREIGN KEY ("TrainingTypeId") REFERENCES "LookupCode" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_SheriffTraining_User_UpdatedById" FOREIGN KEY ("UpdatedById") REFERENCES "User" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "RolePermission" (
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "CreatedById" uuid NULL,
