CREATE TABLE "Shift" (
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 200),
    "Type" integer NOT NULL,
    "StartDate" timestamp with time zone NOT NULL,
    "EndDate" timestamp with time zone NOT NULL,
    "LocationId" integer NULL,
    "CreatedById" uuid NULL,
    "CreatedOn" timestamp with time zone NOT NULL,
    "UpdatedById" uuid NULL,
    "UpdatedOn" timestamp with time zone NULL,
    CONSTRAINT "PK_Shift" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Shift_Location_LocationId" FOREIGN KEY ("LocationId") REFERENCES "Location" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_Shift_User_CreatedById" FOREIGN KEY ("CreatedById") REFERENCES "User" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_Shift_User_UpdatedById" FOREIGN KEY ("UpdatedById") REFERENCES "User" ("Id") ON DELETE SET NULL
);

CREATE TABLE "ShiftSheriff" (
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 200),
    "SheriffId" uuid NOT NULL,
    "ShiftId" integer NOT NULL,
    "CreatedById" uuid NULL,
    "CreatedOn" timestamp with time zone NOT NULL,
    "UpdatedById" uuid NULL,
    "UpdatedOn" timestamp with time zone NULL,
    CONSTRAINT "PK_ShiftSheriff" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ShiftSheriff_Shift_ShiftId" FOREIGN KEY ("ShiftId") REFERENCES "Shift" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_ShiftSheriff_User_CreatedById" FOREIGN KEY ("CreatedById") REFERENCES "User" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_ShiftSheriff_User_SheriffId" FOREIGN KEY ("SheriffId") REFERENCES "User" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_ShiftSheriff_User_UpdatedById" FOREIGN KEY ("UpdatedById") REFERENCES "User" ("Id") ON DELETE SET NULL
);

