START TRANSACTION;

DROP TABLE "ShiftSheriff";

ALTER TABLE "Shift" DROP COLUMN "Slots";

ALTER TABLE "Shift" ADD "AnticipatedAssignmentId" integer NULL;

ALTER TABLE "Shift" ADD "SheriffId" uuid NULL;

ALTER TABLE "Shift" ADD "Timezone" text NULL;

ALTER TABLE "SheriffTraining" ADD "Timezone" text NULL;

ALTER TABLE "SheriffLeave" ADD "Timezone" text NULL;

ALTER TABLE "SheriffAwayLocation" ADD "Timezone" text NULL;

CREATE TABLE "Assignment" (
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 200),
    "AssignmentType" integer NOT NULL,
    "LookupCodeId" integer NULL,
    "StartDate" timestamp with time zone NULL,
    "EndDate" timestamp with time zone NULL,
    "Timezone" text NULL,
    "Name" text NULL,
    "Monday" boolean NOT NULL,
    "Tuesday" boolean NOT NULL,
    "Wednesday" boolean NOT NULL,
    "Thursday" boolean NOT NULL,
    "Friday" boolean NOT NULL,
    "Saturday" boolean NOT NULL,
    "Sunday" boolean NOT NULL,
    "LocationId" integer NOT NULL,
    "ExpiryDate" timestamp with time zone NULL,
    "ExpiryReason" text NULL,
    "CreatedById" uuid NULL,
    "CreatedOn" timestamp with time zone NOT NULL,
    "UpdatedById" uuid NULL,
    "UpdatedOn" timestamp with time zone NULL,
    CONSTRAINT "PK_Assignment" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Assignment_Location_LocationId" FOREIGN KEY ("LocationId") REFERENCES "Location" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Assignment_LookupCode_LookupCodeId" FOREIGN KEY ("LookupCodeId") REFERENCES "LookupCode" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Assignment_User_CreatedById" FOREIGN KEY ("CreatedById") REFERENCES "User" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_Assignment_User_UpdatedById" FOREIGN KEY ("UpdatedById") REFERENCES "User" ("Id") ON DELETE SET NULL
);

CREATE TABLE "Duty" (
    "Id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 200),
    "StartDate" timestamp with time zone NOT NULL,
    "EndDate" timestamp with time zone NOT NULL,
    "LocationId" integer NOT NULL,
    "ExpiryDate" timestamp with time zone NULL,
    "AssignmentId" integer NULL,
    "ShiftId" integer NOT NULL,
    "Timezone" text NULL,
    "CreatedById" uuid NULL,
    "CreatedOn" timestamp with time zone NOT NULL,
    "UpdatedById" uuid NULL,
    "UpdatedOn" timestamp with time zone NULL,
    CONSTRAINT "PK_Duty" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Duty_Assignment_AssignmentId" FOREIGN KEY ("AssignmentId") REFERENCES "Assignment" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_Duty_Location_LocationId" FOREIGN KEY ("LocationId") REFERENCES "Location" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_Duty_Shift_ShiftId" FOREIGN KEY ("ShiftId") REFERENCES "Shift" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_Duty_User_CreatedById" FOREIGN KEY ("CreatedById") REFERENCES "User" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_Duty_User_UpdatedById" FOREIGN KEY ("UpdatedById") REFERENCES "User" ("Id") ON DELETE SET NULL
);

